  `asset_trading_financial_assets` decimal(20,2) DEFAULT NULL,
  `asset_construction_in_progress` decimal(20,2) DEFAULT NULL,
  `asset_total_assets` decimal(20,2) DEFAULT NULL,
  `asset_total_assets_yoy_growth` decimal(15,4) DEFAULT NULL,
