/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `income_sheet` (
  `serial_number` int NOT NULL AUTO_INCREMENT,
  `stock_code` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `stock_abbr` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `report_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `report_period` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `report_year` int NOT NULL,
  `total_operating_revenue` decimal(20,2) DEFAULT NULL,
  `operating_expense_cost_of_sales` decimal(20,2) DEFAULT NULL,
  `operating_expense_selling_expenses` decimal(20,2) DEFAULT NULL,
  `operating_expense_administrative_expenses` decimal(20,2) DEFAULT NULL,
  `operating_expense_financial_expenses` decimal(20,2) DEFAULT NULL,
  `operating_expense_rnd_expenses` decimal(20,2) DEFAULT NULL,
  `operating_expense_taxes_and_surcharges` decimal(20,2) DEFAULT NULL,
  `total_operating_expenses` decimal(20,2) DEFAULT NULL,
  `operating_profit` decimal(20,2) DEFAULT NULL,
  `total_profit` decimal(20,2) DEFAULT NULL,
  `net_profit` decimal(20,2) DEFAULT NULL,
  `asset_impairment_loss` decimal(20,2) DEFAULT NULL,
  `credit_impairment_loss` decimal(20,2) DEFAULT NULL,
  `other_income` decimal(20,2) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `unit_raw` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原始单位',
  `unit_std` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'wan_yuan',
  PRIMARY KEY (`serial_number`),
  UNIQUE KEY `unique_company_period` (`stock_code`,`report_year`,`report_period`)
) ENGINE=InnoDB AUTO_INCREMENT=41694 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
