  `id` int NOT NULL AUTO_INCREMENT,
  `stock_code` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `stock_abbr` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `report_year` int DEFAULT NULL,
  `report_period` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_file` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `report_unit` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `unit_factor` decimal(20,4) DEFAULT NULL,
  `unit_source_text` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `extract_confidence` decimal(5,2) DEFAULT NULL,
  `review_status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'pending',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `fields_total` int DEFAULT '0',
  `fields_valid` int DEFAULT '0',
  `fields_flagged` int DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_report` (`stock_code`,`report_year`,`report_period`)
) ENGINE=InnoDB AUTO_INCREMENT=31448 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
